// This file was generated by Slater.app - countdown-next-race.js


/* ------------------------------------------------------------------
   Race Countdown — DD:HH:MM:SS to the nearest future race
   ------------------------------------------------------------------
   Requires:
   - GSAP
   - The edited Number Odometer script (persistent mode + direction
     + proportional digit widths)
   - The loader's dynamic-target edit (window.loaderTargets registry)

   Webflow setup:
   - Countdown element: [data-countdown] + [data-odometer-element]
     + data-loader-target="countdown"
     placeholder text "00:00:00:00" (no spaces!), NO data-odometer-group
   - Race times: hidden text elements with [data-race-time]
   - Race name label: [data-countdown-name] on the p above the
     countdown — filled with the upcoming race's title, read from
     [data-race-name] inside the same .agenda_item (aria-label
     preferred, so SplitText markup doesn't matter)

   Colon spacing:
   - The odometer rebuilds the element's innerHTML on every roll, so
     hand-placed spans/classes inside the element are destroyed —
     never put custom markup inside an odometer element. The colon
     spacing lives in site CSS instead, targeting the spans the
     script itself generates:

       [data-countdown] [data-odometer-part="static"] {
         padding: 0 0.3rem !important;
         margin: 0 !important;
       }

     (!important overrides the Osmo base bleed padding/margin.)
     With no space characters in the value, the only statics are
     the three colons, so this targets exactly them.

   EDIT (perf — visibility gating): while the countdown is
   off-screen, ticks do zero DOM work. On re-entry the exact
   current value is seated instantly (no catch-up roll), then
   normal ticking resumes.

   EDIT (race name): label selector now matches the live Webflow
   attribute [data-countdown-name], and titles are read from
   [data-race-name] instead of a bare h3.

   EDIT (revert fix): the loader's Phase 3 SplitText.revert()
   restores the label markup captured at SPLIT time. If fonts.ready
   resolved before this script executed, that capture is the Webflow
   placeholder — the reveal would end by snapping the label back.
   The loader now dispatches `loader:text-revealed` after reverting;
   syncLabel re-asserts the race name on that event, making script
   order irrelevant.

   EDIT (season over): when no race date is in the future, the label
   keeps its static Webflow text ('Next race') — restored if the
   last race passes mid-session — and the countdown shows
   CONFIG.noRaceText ('TBA'). Digitless values NEVER go through the
   odometer: nothing rolls, and the per-character static spans it
   generates would pick up the colon-spacing CSS padding and
   letterspace the word. They are set as plain text instead (the
   loader has the matching guard for its roll-in).

   EDIT (cold-load fix): the ticker no longer infers "loader done"
   from computed styles alone — on cold loads it could tick before
   the loader script initialized, adopt the element, and fight the
   fromBlank roll-in so the countdown never started empty. It now
   waits for window.loaderComplete (set by the loader's timeline
   onComplete and every early-exit path) whenever a .loader_wrapper
   exists, with the existing 12s timeout as the failsafe.
------------------------------------------------------------------- */

function initRaceCountdown() {

  // ================================================================
  // CONFIG
  // ================================================================
  const CONFIG = {
    selectors: {
      countdown: '[data-countdown]',
      raceTime: '[data-race-time]',
      label: '[data-countdown-name]', // EDIT (race name)
      raceItem: '.agenda_item',
      raceTitle: '[data-race-name]', // EDIT (race name)
    },

    // EDIT (colon spacing): no spaces around the colons — the
    // visual gap comes from CSS padding on the generated static
    // spans (see header). Keep placeholder text in Webflow in sync.
    separator: ':',
    maxDays: 99,

    tick: {
      duration: 0.45,
      ease: 'power2.out',
    },

    loaderWait: {
      pollMs: 250,
      timeout: 12, // seconds
    },

    // EDIT (perf): ticking resumes slightly before the countdown
    // scrolls into view so it's never seen mid-resync
    viewport: {
      rootMargin: '15%',
    },

    // EDIT (season over): shown when no future race exists.
    // Keep it free of digits and colons.
    noRaceText: 'TBA',
  }
  // ================================================================

  const el = document.querySelector(CONFIG.selectors.countdown)
  if (!el) return

  const labelEl = document.querySelector(CONFIG.selectors.label)
  // EDIT (season over): original Webflow text ('Next race'), used
  // whenever there is no upcoming race. Captured before any write
  // and before the loader splits, so it's the clean static string.
  const labelInitialText = labelEl ? labelEl.textContent.trim() : ''
  const prefersReducedMotion =
    window.matchMedia('(prefers-reduced-motion: reduce)').matches

  // ----------------------------------------------------------------
  // Parse race times
  // ----------------------------------------------------------------
  const MONTHS = {
    january: 0,
    february: 1,
    march: 2,
    april: 3,
    may: 4,
    june: 5,
    july: 6,
    august: 7,
    september: 8,
    october: 9,
    november: 10,
    december: 11,
  }

  function parseRaceDate(text) {
    const m = text.trim().match(
      /^([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})\s+(\d{1,2}):(\d{2})$/
    )
    if (m && MONTHS[m[1].toLowerCase()] !== undefined) {
      return new Date(+m[3], MONTHS[m[1].toLowerCase()], +m[2], +m[4], +m[5])
    }
    const d = new Date(text.trim())
    return isNaN(d.getTime()) ? null : d
  }

  const races = gsap.utils.toArray(CONFIG.selectors.raceTime)
    .map(node => {
      const date = parseRaceDate(node.textContent)
      if (!date) return null
      const item = node.closest(CONFIG.selectors.raceItem)
      const titleEl = item && item.querySelector(CONFIG.selectors.raceTitle)
      // aria-label first — SplitText shreds textContent into word
      // divs but leaves the aria-label as the clean original string
      const title = titleEl ?
        (titleEl.getAttribute('aria-label') || titleEl.textContent.trim()) :
        ''
      return { date, title }
    })
    .filter(Boolean)
    .sort((a, b) => a.date - b.date)

  if (!races.length) {
    console.warn('[countdown] No parseable [data-race-time] elements found.')
    window.loaderDynamicTextReady = true // never stall the loader split
    return
  }

  // ----------------------------------------------------------------
  // Target selection + formatting
  // ----------------------------------------------------------------
  let currentRace = null

  function nextFutureRace() {
    const now = Date.now()
    return races.find(r => r.date.getTime() > now) || null
  }

  function pad(n) {
    return String(n).padStart(2, '0')
  }

  function formatRemaining(ms) {
    let s = Math.max(0, Math.floor(ms / 1000))
    const days = Math.min(CONFIG.maxDays, Math.floor(s / 86400))
    s -= Math.floor(s / 86400) * 86400
    const hours = Math.floor(s / 3600)
    s -= hours * 3600
    const minutes = Math.floor(s / 60)
    const seconds = s - minutes * 60
    return [pad(days), pad(hours), pad(minutes), pad(seconds)]
      .join(CONFIG.separator)
  }

  function textAt(timestamp) {
    if (!currentRace) return CONFIG.noRaceText
    return formatRemaining(currentRace.date.getTime() - timestamp)
  }

  function currentText() {
    return textAt(Date.now())
  }

  function syncLabel() {
    if (!labelEl) return
    // EDIT (season over): no upcoming race → restore the static text
    labelEl.textContent = currentRace ? currentRace.title : labelInitialText
  }

  // ----------------------------------------------------------------
  // Init — write the live value (fallback + no-loader pages) and
  // register the dynamic target provider the loader calls at roll
  // time. leadMs = the roll duration, so the returned value is the
  // one that's true when the roll LANDS.
  // ----------------------------------------------------------------
  currentRace = nextFutureRace()
  el.textContent = currentText()
  syncLabel()

  // EDIT (pre-split seating): tell the loader the race name is in
  // the DOM — it holds its SplitText step for this flag (bounded),
  // so the split always captures the real name. The label then
  // animates and reverts like any other reveal text.
  window.loaderDynamicTextReady = true

  // EDIT (revert fix): the loader's reveal ends with a SplitText
  // revert that can restore pre-name placeholder markup — re-assert
  // the race name whenever a reveal completes. Idempotent, so
  // multiple reveal groups firing this is harmless.
  window.addEventListener('loader:text-revealed', syncLabel)

  window.loaderTargets = window.loaderTargets || {}
  window.loaderTargets.countdown = function (leadMs) {
    // Keep the race pointer fresh in case one passed since init
    if (currentRace && currentRace.date.getTime() <= Date.now()) {
      currentRace = nextFutureRace()
      syncLabel()
    }
    return textAt(Date.now() + (leadMs || 0))
  }

  // ----------------------------------------------------------------
  // Ticker — hands-off until the loader is done with the element
  // ----------------------------------------------------------------
  let started = false
  let lastText = el.textContent.trim()
  const startedAt = Date.now()

  function loaderDoneWithElement() {
    // EDIT (cold-load fix): a page WITH a loader is never "done"
    // until the loader says so. Style checks alone misread the gap
    // before the loader script initializes (element still visible,
    // no roller) as "finished" — on cold loads the ticker then
    // started early and fought the fromBlank roll-in.
    if (document.querySelector('.loader_wrapper') && !window.loaderComplete) {
      return false
    }
    // Tail guard: the roll's own animation outlives the timeline
    const cs = getComputedStyle(el)
    const visible = cs.visibility !== 'hidden' && parseFloat(cs.opacity) > 0.99
    const rolling = !!el.querySelector('[data-odometer-part="roller"]')
    return visible && !rolling
  }

  function applyText(text) {
    const update =
      typeof window.updateOdometer === 'function' ? window.updateOdometer : null
    // EDIT (season over): digitless text ('TBA') is set directly —
    // see header for why it must never enter the odometer
    if (prefersReducedMotion || !update || !/\d/.test(text)) {
      el.textContent = text
      return
    }
    update(el, text, {
      persistent: true,
      direction: 'down',
      duration: CONFIG.tick.duration,
      ease: CONFIG.tick.ease,
    })
  }

  // EDIT (perf): instant seat used when the countdown re-enters the
  // viewport — same persistent path, zero duration, no visible roll
  function resyncNow() {
    lastText = currentText()
    const update =
      typeof window.updateOdometer === 'function' ? window.updateOdometer : null
    if (prefersReducedMotion || !update || !/\d/.test(lastText)) {
      el.textContent = lastText
      return
    }
    update(el, lastText, {
      persistent: true,
      direction: 'down',
      duration: 0,
      ease: 'none',
    })
  }

  // EDIT (perf): visibility gate. Defaults to true so behavior is
  // unchanged until the observer reports otherwise.
  let onScreen = true
  const io = new IntersectionObserver(entries => {
    const was = onScreen
    onScreen = entries[0].isIntersecting
    if (onScreen && !was && started) resyncNow()
  }, { rootMargin: CONFIG.viewport.rootMargin })
  io.observe(el)

  function tick() {
    // Race pointer freshness stays cheap and always on
    if (currentRace && currentRace.date.getTime() <= Date.now()) {
      currentRace = nextFutureRace()
      syncLabel()
    }

    if (!started) {
      const timedOut =
        (Date.now() - startedAt) / 1000 > CONFIG.loaderWait.timeout
      if (!loaderDoneWithElement() && !timedOut) return
      started = true
      // Adopt the loader's landed (lead-compensated) value as our
      // baseline instead of "correcting" toward a stale init value
      lastText = el.textContent.trim()
      return
    }

    // EDIT (perf): off-screen → no formatting, no DOM, nothing
    if (!onScreen) return

    const text = currentText()
    if (text === lastText) return
    lastText = text
    applyText(text)
  }

  setInterval(tick, CONFIG.loaderWait.pollMs)
}

initRaceCountdown();


